import{_ as t,o as n,c as e,a3 as s}from"./chunks/framework.DhF4LrUq.js";const a="/shipperdog/snapshot/screenshots/portal/download-guidance.png",m=JSON.parse('{"title":"Install on Android","description":"Install an Android build from the Tester Portal - the one-time install permission and the download.","frontmatter":{"description":"Install an Android build from the Tester Portal - the one-time install permission and the download."},"headers":[],"relativePath":"how-to/portal/install-android.md","filePath":"how-to/portal/install-android.md"}'),r={name:"how-to/portal/install-android.md"};function i(l,o,d,p,h,c){return n(),e("div",null,[...o[0]||(o[0]=[s('<h1 id="install-on-android" tabindex="-1">Install on Android <a class="header-anchor" href="#install-on-android" aria-label="Permalink to &quot;Install on Android&quot;">​</a></h1><p>From any version page, tap <strong>Download Android build</strong>. The portal first checks you may have this build, then shows one short screen before the file arrives.</p><p><img src="'+a+'" alt="The download screen shown before the install"></p><ol><li><p><strong>Read the one-time permission note.</strong> Android asks for a permission before a browser can install an app. If the download does not install automatically: open <strong>Settings</strong>, then <strong>Apps</strong>, then your browser (Chrome), then <strong>Install unknown apps</strong>, and allow installs from this source. You only ever do this once per browser.</p></li><li><p><strong>Tap <code>Continue to download</code>.</strong> The app file (an APK) downloads straight from the portal&#39;s secure link — the screen shows the file name, its size, and how long the link stays valid (a few minutes; if it lapses, just tap Download again for a fresh one).</p></li><li><p><strong>Open the file</strong> (from the notification or your Downloads) and confirm the install. Android shows its own install screen — that final confirm is your phone&#39;s design, not the portal&#39;s.</p></li></ol><div class="tip custom-block"><p class="custom-block-title">TIP</p><p>If the portal says <strong>This build is not available</strong>, the team pulled the build or your access changed — ask them, or tap Retry if you were mid-flow.</p></div><p><strong>Next:</strong> the build is on your phone — <a href="/shipperdog/snapshot/how-to/portal/feedback">report what you find</a>.</p>',6)])])}const u=t(r,[["render",i]]);export{m as __pageData,u as default};
